import sys
from collections import deque

def findString(N, K):
    if N == 1:
        return ''.join(str(i) for i in range(K))

    # We use Hierholzer's algorithm to find Eulerian circuit
    # Nodes are strings of length N-1
    # Edges represent adding a character

    adj = {}
    visited_edges = set()

    # Initialize adjacency list
    for i in range(K ** (N - 1)):
        node = ""
        temp = i
        for _ in range(N - 1):
            node = str(temp % K) + node
            temp //= K
        adj[node] = []
        for c in range(K):
            adj[node].append(c)

    # To keep track of used edges efficiently
    # We'll use a pointer for each node to avoid checking all edges repeatedly
    edge_ptr = {node: 0 for node in adj}

    def dfs(u):
        while edge_ptr[u] < len(adj[u]):
            c = adj[u][edge_ptr[u]]
            edge_ptr[u] += 1

            v = u[1:] + str(c)
            if dfs(v):
                result.append(c)
                return True
        return False

    result = []
    start_node = "0" * (N - 1)
    dfs(start_node)

    # The result list contains the last character of each edge in reverse order
    # The full string is start_node + reversed(result)
    return start_node + "".join(reversed(result))

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        parts = list(map(int, line.split()))
        if len(parts) >= 2:
            N, K = parts[0], parts[1]
            res = findString(N, K)
            print(res)
    except Exception:
        pass

if __name__ == "__main__":
    main()
